      seasonDigestEl.style.setProperty("--sd-bg", sCfg.bg);
      seasonDigestRefs.badge.textContent = zCfg.badge + (curElevSeason === realNowSeason ? " \u2022 Εποχή μας τώρα" : "");
      seasonDigestRefs.temp.textContent = "\uD83C\uDF21\uFE0F " + zCfg.temp;
