      if (r.sunDisc) { r.sunDisc.setAttribute("fill", sc.sunFill); r.sunDisc.setAttribute("r", sc.sunR); }
      if (r.cloudMain) r.cloudMain.setAttribute("fill", sc.cloudFill);
      if (r.skyAutumn) r.skyAutumn.style.display = (sKey === "autumn") ? "" : "none";
      if (r.skyWinter) r.skyWinter.style.display = (sKey === "winter") ? "" : "none";
      if (r.sea) r.sea.setAttribute("fill", sc.sea);
      if (r.z0Summer) r.z0Summer.style.display = (sKey === "summer") ? "" : "none";
      if (r.z0Waves) r.z0Waves.style.display = (sKey === "autumn" || sKey === "winter") ? "" : "none";
      if (r.z1Ground) r.z1Ground.setAttribute("fill", sc.z1);
      if (r.z1Spring) r.z1Spring.style.display = (sKey === "spring") ? "" : "none";
      if (r.z1Summer) r.z1Summer.style.display = (sKey === "summer") ? "" : "none";
      if (r.z1Autumn) r.z1Autumn.style.display = (sKey === "autumn") ? "" : "none";
      if (r.z1Winter) r.z1Winter.style.display = (sKey === "winter") ? "" : "none";
      if (r.z2Ground) r.z2Ground.setAttribute("fill", sc.z2);
