      if (r.z2Tree1) r.z2Tree1.setAttribute("fill", sc.tree1);
      if (r.z2Tree2) r.z2Tree2.setAttribute("fill", sc.tree2);
      if (r.z2Spring) r.z2Spring.style.display = (sKey === "spring") ? "" : "none";
      if (r.z2Autumn) r.z2Autumn.style.display = (sKey === "autumn") ? "" : "none";
      if (r.z2Winter) r.z2Winter.style.display = (sKey === "winter") ? "" : "none";
      if (r.z3Ground) r.z3Ground.setAttribute("fill", sc.z3);
