        closeAnzacOnly(false);
        cratesBoxOpen = true;
        cratesGameOpen = true;
        cratesTrigBtn.classList.add("is-active");
        cratesStage.style.display = "block";
        ensureActiveLockedCrate();
        drawCratesBox();
        requestAnimationFrame(function() {
          scrollInsideModal(cratesStage);
        });
