    function stopDecauvilleAnim(hideTrain) {
      if (trainAnimRaf) {
        cancelAnimationFrame(trainAnimRaf);
        trainAnimRaf = null;
      }
      if (hideTrain) {
        trainPendingArrival = false;
        trainPausedP = 0;
        if (isPastEra) {
          if (mapTrainTrackHi) mapTrainTrackHi.style.display = "";
          if (mapTrainEl) {
            mapTrainEl.setAttribute("transform", "translate(64,356.4)");
            mapTrainEl.style.display = "";
          }
          if (mapSteam1El) { mapSteam1El.setAttribute("cx", "12.5"); mapSteam1El.setAttribute("cy", "-24"); mapSteam1El.setAttribute("r", "3.2"); mapSteam1El.setAttribute("opacity", "0.75"); }
          if (mapSteam2El) { mapSteam2El.setAttribute("cx", "7.5"); mapSteam2El.setAttribute("cy", "-28.5"); mapSteam2El.setAttribute("r", "4.2"); mapSteam2El.setAttribute("opacity", "0.5"); }
        } else {
          if (mapTrainEl) mapTrainEl.style.display = "none";
          if (mapTrainTrackHi) mapTrainTrackHi.style.display = "none";
        }
      } else if (mapTrainEl && mapTrainEl.style.display !== "none") {
        if (mapSteam1El) { mapSteam1El.setAttribute("cx", "12.5"); mapSteam1El.setAttribute("cy", "-24"); mapSteam1El.setAttribute("r", "3.2"); mapSteam1El.setAttribute("opacity", "0.75"); }
        if (mapSteam2El) { mapSteam2El.setAttribute("cx", "7.5"); mapSteam2El.setAttribute("cy", "-28.5"); mapSteam2El.setAttribute("r", "4.2"); mapSteam2El.setAttribute("opacity", "0.5"); }
      }
    }

   function prepareDecauvilleAtStart() {
      stopDecauvilleAnim(false);
      trainPendingArrival = true;
      trainPausedP = 0;
      if (!mapTrainEl) return;
      mapTrainEl.setAttribute("transform", "translate(64,356.4)");
      if (mapSteam1El) { mapSteam1El.setAttribute("cx", "12.5"); mapSteam1El.setAttribute("cy", "-23.5"); mapSteam1El.setAttribute("r", "3.0"); mapSteam1El.setAttribute("opacity", "0.78"); }
      if (mapSteam2El) { mapSteam2El.setAttribute("cx", "7.5"); mapSteam2El.setAttribute("cy", "-28"); mapSteam2El.setAttribute("r", "4.0"); mapSteam2El.setAttribute("opacity", "0.48"); }
      if (mapTrainTrackHi) mapTrainTrackHi.style.display = "";
      mapTrainEl.style.display = "";
    }

   function runDecauvilleTrainAnim(resumeFrac) {
      var startP = (typeof resumeFrac === "number" && resumeFrac > 0 && resumeFrac < 1) ? resumeFrac : 0;
      stopDecauvilleAnim(false);
      trainPendingArrival = false;
      trainPausedP = startP;
      if (!mapTrainEl) return;
      var x0 = 64, y0 = 356.4, dx = 300, dy = 36.7;
      if (startP === 0) {
        mapTrainEl.setAttribute("transform", "translate(" + x0 + "," + y0 + ")");
      }
      if (mapSteam1El) { mapSteam1El.setAttribute("cx", "12.5"); mapSteam1El.setAttribute("cy", "-22"); mapSteam1El.setAttribute("r", "2.6"); mapSteam1El.setAttribute("opacity", "0.9"); }
      if (mapSteam2El) { mapSteam2El.setAttribute("cx", "6.0"); mapSteam2El.setAttribute("cy", "-28"); mapSteam2El.setAttribute("r", "4.0"); mapSteam2El.setAttribute("opacity", "0.42"); }
      if (mapTrainTrackHi) mapTrainTrackHi.style.display = "";
      mapTrainEl.style.display = "";
      var dur = 5200;
      var t0 = performance.now() - startP * dur;
      var stepTrain = function(now) {
        var p = Math.min(1, (now - t0) / dur);
        trainPausedP = (p < 1) ? p : 0;
        var ease = 0.5 - 0.5 * Math.cos(Math.PI * p);
        var tx = x0 + dx * ease;
        var ty = y0 + dy * ease;
        mapTrainEl.setAttribute("transform", "translate(" + tx.toFixed(1) + "," + ty.toFixed(1) + ")");
        if (p < 1) {
          var c1 = (p * 10) % 1;
          var c2 = (p * 10 + 0.5) % 1;
          if (mapSteam1El) {
            mapSteam1El.setAttribute("cx", (12.5 - c1 * 11).toFixed(1));
            mapSteam1El.setAttribute("cy", (-22 - c1 * 10).toFixed(1));
            mapSteam1El.setAttribute("r", (2.6 + c1 * 2.4).toFixed(1));
            mapSteam1El.setAttribute("opacity", ((1 - c1) * 0.9).toFixed(2));
          }
          if (mapSteam2El) {
            mapSteam2El.setAttribute("cx", (12.5 - c2 * 13).toFixed(1));
            mapSteam2El.setAttribute("cy", (-22 - c2 * 12).toFixed(1));
            mapSteam2El.setAttribute("r", (2.6 + c2 * 2.8).toFixed(1));
            mapSteam2El.setAttribute("opacity", ((1 - c2) * 0.85).toFixed(2));
          }
          trainAnimRaf = requestAnimationFrame(stepTrain);
        } else {
          trainAnimRaf = null;
          if (mapSteam1El) { mapSteam1El.setAttribute("cx", "12.5"); mapSteam1El.setAttribute("cy", "-24"); mapSteam1El.setAttribute("r", "3.2"); mapSteam1El.setAttribute("opacity", "0.75"); }
          if (mapSteam2El) { mapSteam2El.setAttribute("cx", "7.5"); mapSteam2El.setAttribute("cy", "-28.5"); mapSteam2El.setAttribute("r", "4.2"); mapSteam2El.setAttribute("opacity", "0.5"); }
        }
      };
      trainAnimRaf = requestAnimationFrame(stepTrain);
    }

