      function buildHistChipsBar(selIdx) {
        var extraTrainBtns = (selIdx === 5)
          ? '<button type="button" class="pfac-hist-chip" data-train-replay="1">\uD83D\uDD04 Ξαναπέρασε το τρενάκι</button>' +
            '<button type="button" class="pfac-hist-chip" data-train-macro="1" style="border-color:#93c5fd;color:#1d4ed8">\uD83D\uDDFA\uFE0F Χάρτης Πιερίας \u2191</button>'
          : '';
        var whereTodayBtn = (selIdx >= 0)
          ? '<button type="button" class="pfac-hist-chip pfac-hist-chip--where" data-hist-where-today="1">\uD83D\uDCCD Πού πέφτει αυτό σήμερα; \u279C</button>'
          : '';
        return '<div class="pfac-grow-steps">' + histStopsData.map(function(hs, i) {
          return '<button type="button" class="pfac-hist-chip' + (i === selIdx ? ' is-active' : '') + '" data-hist-chip="' + i + '">' + hs.chip + '</button>';
        }).join("") + extraTrainBtns + whereTodayBtn + '</div>';
      }

