      function showHistTourStage(tIdx, isManual) {
        var st = histTourStages[tIdx];
        if (!st) return;
        curHistTourStageIdx = tIdx;
        spatialBridgeHistIdx = -1;
        activeHistIdx = st.histIdx;
        activeSpecialNode = "";
        curGrowStageIdx = -1;
        growActiveFacIdx = -1;
        var hs = histStopsData[st.histIdx];
        var isCart = (pfacTravelMode === "bike");
        if (st.histIdx === 5) {
          prepareDecauvilleAtStart();
          preloadImg(optZoomUrl(decauvillePhotos[0].src));
        } else {
          stopDecauvilleAnim(true);
        }
        setMapStatusHtml(
          isCart ? st.cartMsg : st.msg,
          hs.act,
          hs.img,
          hs.cap,
          { steps: st.walkCfg.steps, meters: st.walkCfg.meters, bikeTime: st.walkCfg.bikeTime, crossRoad: st.walkCfg.crossRoad, safety: hs.safety, bikeSafety: hs.bikeSafety },
          buildHistChipsBar(st.histIdx),
          hs.fallbackImg || "",
          hs.fallbackCap || ""
        );
        var wCfg = st.walkCfg;
        runNeighborhoodWalk({
          dur: (isManual && wCfg.dur) ? 3600 : wCfg.dur, cx: wCfg.cx, cy: wCfg.cy, color: wCfg.color,
          steps: wCfg.steps, meters: wCfg.meters, bikeTime: wCfg.bikeTime,
          crossRoad: wCfg.crossRoad, isRail: wCfg.isRail, crossPt: wCfg.crossPt,
          pts: wCfg.pts, walkerPt: wCfg.walkerPt,
          onArrive: (st.histIdx === 5) ? function() {
            if (isPastEra && activeHistIdx === 5) {
              runDecauvilleTrainAnim(0);
              if (!mapScrollUserAbort) scrollZoomedMapToX(220, true, 355);
            }
          } : null
        });
      }

      function scheduleHistStageTimer(tIdx) {
        if (histTourTimer) { clearTimeout(histTourTimer); histTourTimer = null; }
        if (!isHistTourRunning) return;
        var st = histTourStages[tIdx];
        if (!st) return;
        var effWalkMs = st.walkCfg.dur
          ? (pfacTravelMode === "bike" ? Math.round(st.walkCfg.dur * 1.12) : st.walkCfg.dur)
          : 1500;
        var holdMs = 2600 + (st.extraHoldMs || 0);
        if (tIdx < histTourStages.length - 1) {
          histTourTimer = setTimeout(function() {
            if (!isHistTourRunning) return;
            showHistTourStage(tIdx + 1, false);
            scheduleHistStageTimer(tIdx + 1);
          }, effWalkMs + holdMs);
        } else {
          histTourTimer = setTimeout(function() {
            if (!isHistTourRunning) return;
            stopNeighborhoodWalkAnim(false);
            if (mapCrossAlertEl) mapCrossAlertEl.style.display = "none";
            setStaticWalkPath("M 342,102 L 342,248 M 232,302 L 232,248 L 845,248 L 845,102 M 526,336 L 526,248 M 548,248 L 548,178 L 688,178 L 688,104");
            lastMapTargetX = 548;
            lastMapTargetY = 195;
            scrollZoomedMapToX(548, true, 195);
            stopGrowTour();
            if (histTourBtn) histTourBtn.textContent = "\uD83D\uDD04 Ξαναδές 1924\u20131950!";
          }, effWalkMs + 2800);
        }
      }

      function startHistTour() {
        stopGrowTour(true);
        if (!isPastEra) setNeighborhoodEra(true, true);
        isHistTourRunning = true;
        if (histTourBtn) {
          histTourBtn.classList.add("is-playing");
          histTourBtn.textContent = "\u23F9\uFE0F Σταμάτα (1924\u20131950)";
        }
        showHistTourStage(0, false);
        scheduleHistStageTimer(0);
      }

     if (histTourBtn) {
        histTourBtn.addEventListener("click", function(e) {
          e.stopPropagation();
          if (isPfacDetActive()) stopPfacDet(false, true);
          if (isHistTourRunning) {
            stopGrowTour(true);
            selectHistMapNode(0, false);
          } else {
            startHistTour();
          }
        });
      }
      function selectHistMapNode(idx, playIntroTrain, fromSpatialBridge) {
        var clean = (idx + histStopsData.length) % histStopsData.length;
        stopGrowTour(true);
        spatialBridgeHistIdx = -1;
        activeHistIdx = clean;
        activeSpecialNode = "";
        curGrowStageIdx = -1;
        growActiveFacIdx = -1;
        var hs = histStopsData[clean];
        var isBike = (pfacTravelMode === "bike");
        if (clean !== 5 && !playIntroTrain) {
          stopDecauvilleAnim(true);
        }
        var prefixPast = fromSpatialBridge ? "\uD83D\uDE80\u2794\uD83D\uDD70\uFE0F <strong>Στο ίδιο σημείο τότε (1924\u20131950):</strong> " : "";
        setMapStatusHtml(
          prefixPast + (isBike ? hs.bike : hs.walk),
          hs.act,
          hs.img,
          hs.cap,
          { steps: hs.steps, meters: hs.meters, bikeTime: hs.bikeTime, crossRoad: hs.crossRoad, safety: hs.safety, bikeSafety: hs.bikeSafety },
          buildHistChipsBar(clean),
          hs.fallbackImg || "",
          hs.fallbackCap || ""
        );
        if (clean === 5) {
          prepareDecauvilleAtStart();
          preloadImg(optZoomUrl(decauvillePhotos[0].src));
        } else if (playIntroTrain) {
          if (isMapInView || isMapZoomed) runDecauvilleTrainAnim(0);
          else prepareDecauvilleAtStart();
        }
        runNeighborhoodWalk({
          cx: hs.cx, cy: hs.cy, color: hs.color,
          steps: hs.steps, meters: hs.meters, bikeTime: hs.bikeTime,
          crossRoad: hs.crossRoad, isRail: hs.isRail, crossPt: hs.crossPt,
          pts: hs.pts, walkerPt: hs.walkerPt,
         onArrive: (clean === 5) ? function() {
            if (isPastEra && activeHistIdx === 5 && !activeSpecialNode) {
              runDecauvilleTrainAnim(0);
              if (!mapScrollUserAbort) scrollZoomedMapToX(220, true, 355);
            }
          } : null
        });
      }

      showNeighborhoodHistSpot = function(hIdx) {
        if (isPfacDetActive()) stopPfacDet(false, true);
        stopGrowTour();
        if (mapReplayTimer) { clearTimeout(mapReplayTimer); mapReplayTimer = null; }
        if (!isPastEra) setNeighborhoodEra(true, true);
        selectHistMapNode(hIdx, false, true);
      };

