          var r = stageEl.getBoundingClientRect();
          if (!r.width || !r.height) return false;
          var sxPct = Math.max(0, Math.min(100, ((clientX - r.left) / r.width) * 100));
          var syPct = Math.max(0, Math.min(100, ((clientY - r.top) / r.height) * 100));
